llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C46"],
      "claim": "Diclofenac, a high-transfer acidic NSAID analogue, has an absolute oral bioavailability of 54% in humans after oral administration, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C41"],
      "claim": "Suvorexant, a lipophilic heteroaromatic drug with high transferability, has an absolute oral bioavailability of 82% in humans under fasted conditions.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Brotizolam, a thiophene-containing lipophilic drug, has an absolute oral bioavailability of 70% in young subjects after oral dosing.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Indomethacin, an NSAID analogue, has an absolute oral bioavailability of about 85% in adults given conventional capsules, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C42"],
      "claim": "Alfuzosin, a moderately polar heteroaromatic drug, has an absolute oral bioavailability of 49% in humans under fed conditions, still well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C60"],
      "claim": "Iclepertin, a sulfonyl/heteroaromatic drug, has an absolute oral bioavailability of 72% in humans for a 25 mg tablet under fasted conditions.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C55"],
      "claim": "Etoposide, a complex polar glycoside, has an absolute oral bioavailability of 57 ± 35% in patients, supporting F ≥ 20% despite variability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Lumiracoxib, a COX-2 inhibitor structurally related to the query's NSAID class, has an absolute oral bioavailability of 74.0 ± 8.6% in healthy subjects.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues show absolute oral bioavailability well above 20% in humans (49–85% or higher), and the query shares lipophilic, heteroaromatic, and sulfonamide-like features consistent with good absorption; no transferable evidence supports F < 20%.",
  "evidence_gaps": [
    "No direct pharmacokinetic data are available for the exact query molecule.",
    "Formulation-dependent absorption and first-pass/efflux behavior for the query are not directly measured.",
    "Some analogue low-F values occur only in special populations such as preterm infants and are not applicable to adult oral dosing."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

